#!/usr/bin/env bash
# Inscriptions aux cours — BACKEND (avec MIGRATION 20261220000000_course_enrollment).
# - modèle CourseEnrollment (membre ↔ créneau, effacé avec l'un ou l'autre) ;
# - course.listForEnrollment, user.coursesOf, user.setCourses ; user.create accepte courseIds ;
# - contrats : MINOR_AUDIENCES (enfants, adolescents) = indice de minorité.
# Prérequis : apply-majorite-tri.sh. Ensuite : apply-inscriptions-cours-ecrans.sh.
# Usage (racine du repo) : bash apply-inscriptions-cours-backend.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"prisma/schema.prisma" 2>/dev/null | grep -qF "model CourseEnrollment"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "markAdults" "packages/backend/src/modules/users/router.ts" 2>/dev/null || { echo "lancez d'abord apply-majorite-tri.sh"; exit 1; }
MODIFIED=("apps/web/src/features/docs/entities/procedureMap.generated.json" "packages/backend/src/modules/courses/router.ts" "packages/backend/src/modules/users/router.ts" "prisma/schema.prisma")
CREATED=("packages/contracts/src/courses/enrollment.ts" "prisma/migrations/20261220000000_course_enrollment/migration.sql")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "prisma/migrations/20261220000000_course_enrollment" 2>/dev/null || true; rmdir -p "packages/contracts/src/courses" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "model CourseEnrollment" "prisma/schema.prisma" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "packages/contracts/src/courses"
